<?php $kind=\Chengyu\Core\Input::choice($_GET['kind']??'shipping',['shipping','promotion']);$table=$kind==='shipping'?'cy_shipping_templates':'cy_promotions';$rows=$a->db->all('SELECT * FROM '.$table.' ORDER BY id DESC LIMIT 200');$edit=!empty($_GET['edit'])?$a->db->one('SELECT * FROM '.$table.' WHERE id=?',[\Chengyu\Core\Input::integer($_GET['edit'],1)]):null;
$example=$kind==='shipping'?['mode'=>'piece','default'=>['first'=>1,'first_fee'=>600,'step'=>1,'step_fee'=>200,'free_above'=>9900],'zones'=>['CN-XJ'=>['first'=>1,'first_fee'=>1800,'step'=>1,'step_fee'=>500,'free_above'=>0]]]:['type'=>'threshold_fixed','group'=>'order','min_amount'=>10000,'discount'=>1000,'min_tier'=>0,'item_ids'=>[]]; ?>
<section class="page-hero"><div><span class="eyebrow">RULEBOOK / EXACT CENTS</span><h1><?= e($title) ?></h1><p><?= t('Versioned rules, deterministic stacking and exact per-unit allocation.') ?></p></div><?= icon('gift') ?></section><div class="row wrap section"><a class="btn secondary" href="<?= e(au('shipping',['kind'=>'shipping'])) ?>"><?= t('Shipping templates') ?></a><a class="btn secondary" href="<?= e(au('shipping',['kind'=>'promotion'])) ?>"><?= t('Promotions') ?></a></div>
<div class="commerce-grid"><section class="panel glass commerce-panel"><?= form_start('admin_rule_save',au('shipping',['kind'=>$kind]),'',false).hidden('kind',$kind).hidden('id',$edit['id']??0).hidden('revision',$edit['revision']??0) ?><?php field('name','Name',$edit['name']??'');field('document','Rule JSON',json_encode($edit?json_decode($edit['document'],true):$example,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),'textarea',['required'=>'required','rows'=>'16','spellcheck'=>'false']);check_field('active','Enabled',(bool)($edit['active']??true));if($kind==='promotion'){field('starts_at','Start Unix timestamp (0 = now)',$edit['starts_at']??0,'number',['min'=>'0']);field('ends_at','End Unix timestamp (0 = no end)',$edit['ends_at']??0,'number',['min'=>'0']);}button('Save rule','','check'); ?></form><p class="hint"><?= t('Money values are minor units: 600 means 6.00. Shipping weight steps are grams. A null default denies unmatched regions.') ?></p><p class="hint"><?= t('Promotions: threshold_fixed, percent, nth, buy_get, tiered, bundle. The best discount wins within a group; different groups stack in sorted group-name order. discount_bps=1000 means a 10 percent discount.') ?></p></section>
<aside class="commerce-aside"><section class="panel glass commerce-panel"><h2><?= t('Saved rules') ?></h2><?php foreach($rows as $row): ?><a class="commerce-rule-link" href="<?= e(au('shipping',['kind'=>$kind,'edit'=>$row['id']])) ?>"><strong>#<?= (int)$row['id'] ?> <?= e($row['name']) ?></strong><span class="hint">v<?= (int)$row['revision'] ?> &middot; <?= t($row['active']?'Enabled':'Disabled') ?></span></a><?php endforeach ?></section><?php if($kind==='shipping'): ?><section class="panel glass commerce-panel section"><h2><?= t('Bind a physical product') ?></h2><?= form_start('admin_shipping_bind','','',false) ?><?php field('content_id','Product ID','','number',['required'=>'required','min'=>'1']);$options=[0=>'Free shipping (no template)'];foreach($rows as $row){if($row['active']){$options[$row['id']]='#'.$row['id'].' '.$row['name'];}}select_field('template_id','Shipping template',$options,0);field('weight_grams','Unit weight in grams',0,'number',['min'=>'0','max'=>'1000000']);button('Save product shipping','secondary','box'); ?></form></section><?php endif ?></aside></div>